function parseDeepLink(url) {
  const path = url.replace('myapp://', '');
  const [screen, param] = path.split('/');
  const names = { orders: 'OrderDetail', cart: 'Cart', home: 'Home' };
  return (names[screen] || screen) + ':' + param;
}
console.log(parseDeepLink('myapp://orders/42'));

